PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS academic_levels(id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS academic_sessions(id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, starts_at TEXT, ends_at TEXT, is_active INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, is_system INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS permissions(id TEXT PRIMARY KEY, resource TEXT NOT NULL, action TEXT NOT NULL, description TEXT, UNIQUE(resource,action));
CREATE TABLE IF NOT EXISTS user_roles(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, assigned_by TEXT REFERENCES users(id), assigned_at TEXT NOT NULL DEFAULT(datetime('now')), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions(role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id TEXT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS member_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, profile_photo_key TEXT, date_of_birth TEXT, gender TEXT, address TEXT, emergency_contact TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, membership_id TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', started_at TEXT, expires_at TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS membership_cards(id TEXT PRIMARY KEY, membership_id TEXT NOT NULL REFERENCES memberships(id) ON DELETE CASCADE, qr_token_hash TEXT NOT NULL UNIQUE, issued_at TEXT NOT NULL DEFAULT(datetime('now')), revoked_at TEXT);
CREATE TABLE IF NOT EXISTS hero_slides(id TEXT PRIMARY KEY, image_key TEXT, badge TEXT, title TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', primary_cta_text TEXT, primary_cta_link TEXT, secondary_cta_text TEXT, secondary_cta_link TEXT, display_order INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS pages(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT, body TEXT, hero_image_key TEXT, status TEXT NOT NULL DEFAULT 'draft', published_at TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS page_sections(id TEXT PRIMARY KEY, page_id TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE, title TEXT, body TEXT, image_key TEXT, display_order INTEGER NOT NULL DEFAULT 0, is_published INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS navigation_menus(id TEXT PRIMARY KEY, label TEXT NOT NULL, href TEXT NOT NULL, location TEXT NOT NULL DEFAULT 'header', display_order INTEGER NOT NULL DEFAULT 0, is_visible INTEGER NOT NULL DEFAULT 1, parent_id TEXT REFERENCES navigation_menus(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS system_settings(key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS executive_administrations(id TEXT PRIMARY KEY, name TEXT NOT NULL, starts_at TEXT, ends_at TEXT, is_current INTEGER NOT NULL DEFAULT 0, handover_notes TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS executive_positions(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS executive_assignments(id TEXT PRIMARY KEY, administration_id TEXT NOT NULL REFERENCES executive_administrations(id) ON DELETE CASCADE, position_id TEXT NOT NULL REFERENCES executive_positions(id), user_id TEXT REFERENCES users(id) ON DELETE SET NULL, full_name TEXT NOT NULL, bio TEXT, image_key TEXT, responsibilities TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')), UNIQUE(administration_id,position_id));
CREATE TABLE IF NOT EXISTS news(id TEXT PRIMARY KEY, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, excerpt TEXT, body TEXT, image_key TEXT, category TEXT, status TEXT NOT NULL DEFAULT 'draft', published_at TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS announcements(id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'normal', published_at TEXT, expires_at TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS achievements(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, achieved_at TEXT, image_key TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, title TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, image_key TEXT, starts_at TEXT NOT NULL, ends_at TEXT, venue TEXT, price_minor INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'NGN', capacity INTEGER, registration_open INTEGER NOT NULL DEFAULT 1, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS event_registrations(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, status TEXT NOT NULL DEFAULT 'registered', created_at TEXT NOT NULL DEFAULT(datetime('now')), UNIQUE(event_id,email));
CREATE TABLE IF NOT EXISTS event_tickets(id TEXT PRIMARY KEY, registration_id TEXT NOT NULL REFERENCES event_registrations(id) ON DELETE CASCADE, ticket_code TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'valid', created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS attendance_records(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, registration_id TEXT NOT NULL REFERENCES event_registrations(id) ON DELETE CASCADE, scanned_by TEXT REFERENCES users(id), scanned_at TEXT NOT NULL DEFAULT(datetime('now')), UNIQUE(event_id,registration_id));
CREATE TABLE IF NOT EXISTS gallery_albums(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, cover_key TEXT, is_public INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS gallery_media(id TEXT PRIMARY KEY, album_id TEXT NOT NULL REFERENCES gallery_albums(id) ON DELETE CASCADE, object_key TEXT NOT NULL, caption TEXT, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, category TEXT NOT NULL, object_key TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'public', published_at TEXT, downloads INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS contact_messages(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', reply TEXT, replied_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS payment_categories(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, amount_minor INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), category_id TEXT REFERENCES payment_categories(id), reference TEXT NOT NULL UNIQUE, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'NGN', status TEXT NOT NULL DEFAULT 'unpaid', due_at TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY, invoice_id TEXT REFERENCES invoices(id), user_id TEXT REFERENCES users(id), reference TEXT NOT NULL UNIQUE, provider_reference TEXT, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'NGN', status TEXT NOT NULL DEFAULT 'pending', paid_at TEXT, receipt_url TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS payment_webhook_events(id TEXT PRIMARY KEY, provider TEXT NOT NULL, event_id TEXT NOT NULL UNIQUE, payload_json TEXT NOT NULL, processed_at TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS expenses(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'NGN', status TEXT NOT NULL DEFAULT 'pending', receipt_key TEXT, submitted_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS expense_approvals(id TEXT PRIMARY KEY, expense_id TEXT NOT NULL REFERENCES expenses(id) ON DELETE CASCADE, approver_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL, note TEXT, decided_at TEXT NOT NULL DEFAULT(datetime('now')), UNIQUE(expense_id,approver_id));
CREATE TABLE IF NOT EXISTS financial_records(id TEXT PRIMARY KEY, kind TEXT NOT NULL, category TEXT, description TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'NGN', reference TEXT, recorded_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS elections(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, opens_at TEXT NOT NULL, closes_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS election_positions(id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES elections(id) ON DELETE CASCADE, title TEXT NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, UNIQUE(election_id,title));
CREATE TABLE IF NOT EXISTS election_candidates(id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES elections(id) ON DELETE CASCADE, position_id TEXT NOT NULL REFERENCES election_positions(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id), display_name TEXT NOT NULL, manifesto TEXT NOT NULL, photo_key TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS election_eligibility(election_id TEXT NOT NULL REFERENCES elections(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, eligible INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(election_id,user_id));
CREATE TABLE IF NOT EXISTS election_voters(id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES elections(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, voted_at TEXT NOT NULL DEFAULT(datetime('now')), UNIQUE(election_id,user_id));
CREATE TABLE IF NOT EXISTS election_ballots(id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES elections(id) ON DELETE CASCADE, encrypted_selections TEXT NOT NULL, cast_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS election_results(id TEXT PRIMARY KEY, election_id TEXT NOT NULL REFERENCES elections(id) ON DELETE CASCADE, position_id TEXT NOT NULL REFERENCES election_positions(id) ON DELETE CASCADE, candidate_id TEXT NOT NULL REFERENCES election_candidates(id) ON DELETE CASCADE, vote_count INTEGER NOT NULL DEFAULT 0, published_at TEXT, UNIQUE(election_id,position_id,candidate_id));
CREATE TABLE IF NOT EXISTS welfare_requests(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, category TEXT NOT NULL, subject TEXT NOT NULL, details TEXT NOT NULL, confidential INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'submitted', response TEXT, assigned_to TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT(datetime('now')), updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS complaints(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, subject TEXT NOT NULL, details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', response TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS suggestions(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, subject TEXT NOT NULL, details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', response TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS alumni_profiles(id TEXT PRIMARY KEY, user_id TEXT UNIQUE REFERENCES users(id) ON DELETE SET NULL, full_name TEXT NOT NULL, email TEXT, graduation_year TEXT, profession TEXT, bio TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS sponsors(id TEXT PRIMARY KEY, name TEXT NOT NULL, contact_email TEXT, website TEXT, logo_key TEXT, sponsorship_details TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, price_minor INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'NGN', image_key TEXT, stock INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', amount_minor INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, unit_price_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS notification_reads(notification_id TEXT NOT NULL REFERENCES notifications(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, read_at TEXT NOT NULL DEFAULT(datetime('now')), PRIMARY KEY(notification_id,user_id));
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, resource TEXT NOT NULL, record_id TEXT, details_json TEXT, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS pages_status_idx ON pages(status,published_at);
CREATE INDEX IF NOT EXISTS news_status_idx ON news(status,published_at);
CREATE INDEX IF NOT EXISTS events_starts_idx ON events(starts_at);
CREATE INDEX IF NOT EXISTS assignments_admin_idx ON executive_assignments(administration_id);
CREATE INDEX IF NOT EXISTS audit_logs_created_idx ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS payments_user_status_idx ON payments(user_id,status);
CREATE INDEX IF NOT EXISTS welfare_user_idx ON welfare_requests(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS media_objects(object_key TEXT PRIMARY KEY, uploaded_by TEXT REFERENCES users(id) ON DELETE SET NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS login_attempts(attempt_key TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, window_started_at INTEGER NOT NULL, blocked_until INTEGER, updated_at TEXT NOT NULL DEFAULT(datetime('now')));
